-- Demo data for the help screenshots job and the deals/voice/help e2e spec (section 12c:
-- "demo data only, never her real content"). Every row id starts with demo_ or uses version 9001
-- so tests/e2e/demo.ts can remove it again; brands/pitches/deals/narrations are reset whole
-- because only these specs create them. Idempotent: it clears before it inserts.

DELETE FROM posts WHERE id LIKE 'demo_%';
DELETE FROM narrations;
DELETE FROM deal_emails;
DELETE FROM deal_offers;
DELETE FROM pitches;
DELETE FROM deals;
DELETE FROM media_kit_versions;
DELETE FROM kit_views;
DELETE FROM kit_slugs WHERE slug != 'studio';
DELETE FROM settings WHERE key = 'marketplaces_joined';
DELETE FROM brand_contacts;
DELETE FROM brands;
DELETE FROM account_stats WHERE id LIKE 'demo_%';
DELETE FROM clips WHERE id LIKE 'demo_%';
DELETE FROM assets WHERE id LIKE 'demo_%';
DELETE FROM dumps WHERE id LIKE 'demo_%';
DELETE FROM brand_profile WHERE version = 9001;
DELETE FROM research_briefs WHERE version = 9001;
UPDATE media_kit SET bio = '', photo_r2_key = NULL, featured_clip_ids = '[]', past_partners = '[]', rates = NULL, public_slug = 'studio', contact_email = NULL, updated_at = NULL, draft = NULL, draft_saved_at = NULL WHERE id = 1;
UPDATE voice SET sample_r2_key = NULL, consent_at = NULL, consent_text = NULL, model_r2_key = NULL, elevenlabs_voice_id = NULL, enabled = 0, updated_at = NULL WHERE id = 1;

INSERT INTO brand_profile (version, sections, locked, locked_at, source) VALUES (9001, '{"who": "Demo creator: an everyday lifestyle creator who makes daily routines feel easy.", "audience": "Women 30-55 in the US who love practical routines, quick tips and weekly resets.", "goals": "90 days: post 10 clips a week and land 2 paid partnerships. 1 year: a steady brand-deal income.", "voice": "Warm, gracious, a little playful; short sentences; never salesy.", "themes": "Morning routines\nQuick tips\nWeekly resets\nEveryday wins", "do_dont": "Do: show real days and real results. Don''t: fake reviews or hard selling.", "off_limits": "Alcohol, gambling, diet pills", "deal_fit": "Everyday essentials, wellness, stationery, travel and gifting brands.", "ctas": "Follow for more everyday tips; save this for your next reset."}', 1, '2026-09-20T12:00:00.000Z', 'edited');
