INSERT INTO pitches (id, brand_id, contact_id, subject, body, dm_text, followup_1, followup_2, clip_links, status) VALUES ('demo_pitch_2', 'demo_brand_2', 'demo_ct_2', 'Creator partnership idea: Brightside Bottle Co. × Sam', 'Hi Brightside Bottle Co. team,

I''m Sam, and I share my morning routine on camera most weeks. Your bottle is already in my Sunday reset videos.
My audience: women 30-55 who love practical routines; 12.4K followers on TikTok (about 3.1K views a video).
Two clips that show my style:
https://demo.example/media/1
https://demo.example/media/2
Media kit: http://localhost:8787/kit/studio

Would you be open to a paid partnership this season: one video on TikTok and Instagram featuring your bottles?

Sam', 'Hi Brightside! I share routines with 12K followers on TikTok and I would love to feature your bottles. Media kit: http://localhost:8787/kit/studio', 'Hi again, just floating this back up. Media kit: http://localhost:8787/kit/studio Sam', 'Last note from me on this one. If the timing is wrong, no problem at all. Sam', '[]', 'drafted');
INSERT INTO pitches (id, brand_id, contact_id, subject, body, dm_text, followup_1, followup_2, clip_links, status, sent_at, next_followup_at) VALUES ('demo_pitch_3', 'demo_brand_3', 'demo_ct_3', 'Creator partnership idea: Fieldnote Paper Co. × Sam', 'Hi Fieldnote Paper Co. team,

I''m Sam, and I share my morning routine on camera most weeks. Your notebooks are already in my Sunday reset videos.
My audience: women 30-55 who love practical routines; 12.4K followers on TikTok (about 3.1K views a video).
Two clips that show my style:
https://demo.example/media/1
https://demo.example/media/2
Media kit: http://localhost:8787/kit/studio

Would you be open to a paid partnership this season: one video on TikTok and Instagram featuring your notebooks?

Sam', 'Hi Fieldnote! Media kit: http://localhost:8787/kit/studio', 'Hi again, floating this back up. Sam', 'Last note from me. Sam', '[]', 'sent', '2026-09-20T12:00:00.000Z', '2026-09-25T12:00:00.000Z');

INSERT INTO deal_emails (id, deal_id, scenario, subject, subject_options, body, tone, length, source, status, created_at) VALUES ('demo_email_2', 'demo_deal_2', 'cold_pitch', 'An idea for Brightside Bottle Co.: morning routine content', '["An idea for Brightside Bottle Co.: morning routine content","Brightside Bottle Co. × Sam: a video idea","For your creator team: Morning routines with Brightside Bottle Co."]', 'Hi Brightside Bottle Co. team,

I''m Sam, an everyday lifestyle and quick-tips creator. I noticed your new bottle line is shot in morning routines like mine, so this felt like the right moment to reach out.

My idea: a 30-second Sunday reset using your bottle.

Three ways we could do it:
Full: 2 × TikTok video + Instagram Reel, with 90 days of usage on your channels, $3,360
Standard: TikTok video, $800
Entry: Video for their channels (no post from you), $350

My media kit, with my numbers, past work and rates: http://localhost:8787/kit/studio

Would one of these work for this season? If you have a brief or a budget in mind, I''ll shape it to fit.

Warmly,
Sam', 'warm', 'standard', 'starter', 'draft', '2026-09-22T12:05:00.000Z');
